 \u043f\u0435\u0440\u0435\u043a\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u043b\u0456\u0441\u043e\u0432\u0456 \u0434\u043e\u0440\u043e\u0433\u0438 \u0439 \u043f\u0440\u043e\u0457\u0437\u0434 \u0440\u044f\u0442\u0443\u0432\u0430\u043b\u044c\u043d\u0438\u043a\u0456\u0432."},"zh":{"directions":"\u6240\u5217\u5f92\u6b65\u8def\u6bb5\u4ecePrze\u0142\u0119cz P\u0142oszczyna\u5f00\u59cb\uff0c\u5230Rudawiec\u7ed3\u675f\u3002\u5730\u56fe\u94fe\u63a5\u663e\u793a\u5f92\u6b65\u8def\u7ebf\uff0c\u5e76\u4e0d\u4ee3\u8868\u6c7d\u8f66\u53ef\u5230\u8fbe\u8d77\u70b9\u6216\u53ef\u5408\u6cd5\u505c\u8f66\u3002\n\u6b64\u8def\u7ebf\u4ecePrze\u0142\u0119cz P\u0142oszczyna\u51fa\u53d1\uff0c\u800c\u975eBielice\u3002Nowa Morawa\u7684\u505c\u8f66\u70b9\u5e76\u4e0d\u662fGPX\u8d77\u70b9\u3002","public_transport":"\u5c1a\u672a\u6838\u5b9e\u524d\u5f80\u6b64\u8def\u7ebf\u8d77\u70b9\u7684\u73b0\u884c\u516c\u5171\u4ea4\u901a\u3002\u8bf7\u67e5\u8be2\u51fa\u884c\u5f53\u5929\u7684\u65f6\u523b\u8868\uff0c\u5e76\u5b89\u6392\u8fd4\u7a0b\u3002","warnings":"\u51fa\u53d1\u524d\u8bf7\u67e5\u770b\u5929\u6c14\u3001\u8def\u51b5\u548c\u5f53\u5730\u9650\u5236\u3002\u672c\u6761\u76ee\u4e0d\u4fdd\u8bc1\u8def\u7ebf\u5f53\u524d\u5f00\u653e\u3002\u8bf7\u52ff\u5835\u585e\u6797\u9053\u6216\u6551\u63f4\u901a\u9053\u3002"}},"evidence":[{"field":"walking_start_and_variant","url":"https://dolnoslaskie.szlaki.pttk.pl/675-dolnoslaskie-zloty-stok-rynek-schronisko-pttk-na-sniezniku","checked_on":"2026-11-22"}],"parking":[]},{"peak_slug":"orlica","expected_trail":{"id":22,"peak_id":5,"slug":"orlica-katalog-03","start_point_name":"Torfowisko pod Ziele\u0144cem \u2013 parking","end_point_name":"Lasek Miejski"},"access":{"address":null,"postcode":null,"latitude":null,"longitude":null,"google_maps_url":"https://dolnoslaskie.szlaki.pttk.pl/935-dolnoslaskie-torfowisko-pod-zielencem-parking-lasek-miejski","public_transport_url":null,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/935-dolnoslaskie-torfowisko-pod-zielencem-parking-lasek-mi